31	class kernel_add {
32	   public:
33	    template <int DEPTH>
34	    static void apply(XF_PTNAME(DEPTH) & p, XF_PTNAME(DEPTH) & q, XF_PTNAME(DEPTH) & r, int _policytype) {
35	// clang-format off
36	        #pragma HLS inline
37	        // clang-format on
38	        // for the input type of 8U
39	        if ((DEPTH == XF_8UP) || (DEPTH == XF_24UP)) {
40	            ap_uint<(XF_PIXELDEPTH(DEPTH) + 1)> result_temp;
41	            result_temp = p + q; // perform the addition operation on the input pixels
42	            if (_policytype == XF_CONVERT_POLICY_SATURATE && result_temp > 255) // handling the overflow
43	            {
44	                result_temp = 255;
45	            }
46	            r = (XF_PTNAME(DEPTH))result_temp;
47	        }
48	
49	        // for the input type of 16S
50	        else if ((DEPTH == XF_16SP) || (DEPTH == XF_48SP)) {
51	            ap_int<17> result_temp;
52	            result_temp = p + q; // perform the addition operation on the input pixels
53	            if (_policytype == XF_CONVERT_POLICY_SATURATE && result_temp > 32767) // handling the overflow
54	            {
55	                result_temp = 32767;
56	            } else if (_policytype == XF_CONVERT_POLICY_SATURATE && result_temp < -32768) // handling the overflow
57	            {
58	                result_temp = -32768;
59	            }
60	            r = (XF_PTNAME(DEPTH))result_temp;
61	        }
62	    }
63	};
64	class kernel_sub {
65	   public:
66	    template <int DEPTH>
67	    static void apply(XF_PTNAME(DEPTH) & p, XF_PTNAME(DEPTH) & q, XF_PTNAME(DEPTH) & r, int _policytype) {
68	// clang-format off
69	        #pragma HLS inline
70	        // clang-format on
71	        // for the input type of 8U
72	        if ((DEPTH == XF_8UP) || (DEPTH == XF_24UP)) {
73	            ap_int<(XF_PIXELDEPTH(DEPTH) + 1)> result_temp;
74	            result_temp = p - q; // perform the subtraction operation on the input pixels
75	            if (_policytype == XF_CONVERT_POLICY_SATURATE && result_temp < 0) // handling the overflow
76	            {
77	                result_temp = 0;
78	            }
79	            r = (XF_PTNAME(DEPTH))result_temp;
80	        }
81	
82	        // for the input type of 16S
83	        else if ((DEPTH == XF_16SP) || (DEPTH == XF_48SP)) {
84	            ap_int<(XF_PIXELDEPTH(DEPTH) + 1)> result_temp;
85	            result_temp = p - q; // perform the addition operation on the input pixels
86	            if (_policytype == XF_CONVERT_POLICY_SATURATE && result_temp > 32767) // handling the overflow
87	            {
88	                result_temp = 32767;
89	            } else if (_policytype == XF_CONVERT_POLICY_SATURATE && result_temp < -32768) // handling the overflow
90	            {
91	                result_temp = -32768;
92	            }
93	            r = (XF_PTNAME(DEPTH))result_temp;
94	        }
95	    }
96	};
