167	class kernel_compare {
168	   public:
169	    template <int DEPTH>
170	    static void apply(XF_PTNAME(DEPTH) & p, XF_PTNAME(DEPTH) & q, XF_PTNAME(DEPTH) & r, int comp_op) {
171	// clang-format off
172	        #pragma HLS inline
173	        // clang-format on
174	        XF_PTNAME(DEPTH) Min = 0;
175	        switch (comp_op) {
176	            case XF_CMP_EQ:
177	                r = (p == q ? 255 : 0); // equal
178	                break;
179	            case XF_CMP_GT:
180	                r = (p > q ? 255 : 0); // greater than
181	                break;
182	            case XF_CMP_GE:
183	                r = (p >= q ? 255 : 0); // greater than or equal
184	                break;
185	            case XF_CMP_LT:
186	                r = (p < q ? 255 : 0); // less than
187	                break;
188	            case XF_CMP_LE:
189	                r = (p <= q ? 255 : 0); // less than or equal
190	                break;
191	            case XF_CMP_NE:
192	                r = (p != q ? 255 : 0); // not equal
193	                break;
194	            default:
195	                break;
196	        }
197	    }
198	};
