224	template <int SRC_T,
225	          int ROWS,
226	          int COLS,
227	          int PLANES,
228	          int DEPTH,
229	          int NPC,
230	          int XFCVDEPTH_IN_1 = _XFCVDEPTH_DEFAULT,
231	          int XFCVDEPTH_IN_2 = _XFCVDEPTH_DEFAULT,
232	          int XFCVDEPTH_OUT_1 = _XFCVDEPTH_DEFAULT,
233	          int WORDWIDTH_SRC,
234	          int WORDWIDTH_DST,
235	          int COLS_TRIP>
236	void xFAbsDiffKernel(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_1>& _src1,
237	                     xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_2>& _src2,
238	                     xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_OUT_1>& _dst,
239	                     uint16_t image_height,
240	                     uint16_t image_width) {
241	    //	image_width=image_width>>XF_BITSHIFT(NPC);
242	    ap_uint<13> i, j, k;
243	
244	    XF_SNAME(WORDWIDTH_SRC) val_src1, val_src2;
245	    XF_SNAME(WORDWIDTH_DST) val_dst;
246	    uchar_t result, p, q;
247	    int STEP = XF_PIXELDEPTH(DEPTH) / PLANES;
248	rowLoop:
249	    for (i = 0; i < image_height; i++) {
250	// clang-format off
251	        #pragma HLS LOOP_TRIPCOUNT min=ROWS max=ROWS
252	        #pragma HLS LOOP_FLATTEN off
253	    // clang-format on
254	
255	    colLoop:
256	        for (j = 0; j < image_width; j++) {
257	// clang-format off
258	            #pragma HLS LOOP_TRIPCOUNT min=COLS_TRIP max=COLS_TRIP
259	            #pragma HLS pipeline
260	            // clang-format on
261	
262	            val_src1 =
263	                (XF_SNAME(WORDWIDTH_SRC))(_src1.read(i * image_width + j)); // reading the data from the first stream
264	            val_src2 =
265	                (XF_SNAME(WORDWIDTH_SRC))(_src2.read(i * image_width + j)); // reading the data from the second stream
266	
267	        procLoop:
268	            for (k = 0; k < (XF_WORDDEPTH(WORDWIDTH_SRC)); k += XF_PIXELDEPTH(DEPTH)) {
269	// clang-format off
270	                #pragma HLS unroll
271	                // clang-format on
272	                p = val_src1.range(k + (STEP - 1), k);     // Get bits from certain range of positions.
273	                q = val_src2.range(k + (STEP - 1), k);     // Get bits from certain range of positions.
274	                result = __ABS(p - q);                     // performing absolute difference for the input pixels
275	                val_dst.range(k + (STEP - 1), k) = result; // Set bits in a range of positions.
276	            }
277	            _dst.write(i * image_width + j, (val_dst)); // writing data to the output stream
278	        }
279	    }
280	}
