301	                        xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_OUT_1>& _dst,
302	                        uint16_t image_height,
303	                        uint16_t image_width) {
304	    ap_uint<13> i, j, k;
305	    XF_SNAME(WORDWIDTH_SRC) val_src1, val_src2;
306	    XF_SNAME(WORDWIDTH_DST) val_dst;
307	    XF_PTNAME(DEPTH) result, p, q;
308	    int STEP = XF_PIXELDEPTH(DEPTH) / PLANES;
309	rowLoop:
310	    for (i = 0; i < image_height; i++) {
311	// clang-format off
312	        #pragma HLS LOOP_TRIPCOUNT min=ROWS max=ROWS
313	        #pragma HLS LOOP_FLATTEN off
314	    // clang-format on
315	
316	    colLoop:
317	        for (j = 0; j < image_width; j++) {
318	// clang-format off
319	            #pragma HLS LOOP_TRIPCOUNT min=COLS_TRIP max=COLS_TRIP
320	            #pragma HLS pipeline
321	            // clang-format on
322	
323	            val_src1 = (XF_SNAME(WORDWIDTH_SRC))(_src1.read(
324	                i * image_width + j)); //(_src1.data[i*image_width+j]); // reading the data from the first stream
325	            val_src2 =
326	                (XF_SNAME(WORDWIDTH_SRC))(_src2.read(i * image_width + j)); // reading the data from the second stream
327	
328	        procLoop:
329	            for (k = 0; k < (XF_WORDDEPTH(WORDWIDTH_SRC)); k += STEP) {
330	// clang-format off
331	                #pragma HLS unroll
332	                // clang-format on
333	                p = val_src1.range(k + (STEP - 1), k);     // Get bits from certain range of positions.
334	                q = val_src2.range(k + (STEP - 1), k);     // Get bits from certain range of positions.
335	                result = p & q;                            // performing the bitwiseAND operation
336	                val_dst.range(k + (STEP - 1), k) = result; // Set bits in a range of positions.
337	            }
338	            _dst.write(i * image_width + j, (val_dst)); // writing data to the stream
339	        }
340	    }
