528	          int XFCVDEPTH_IN_1 = _XFCVDEPTH_DEFAULT,
529	          int XFCVDEPTH_IN_2 = _XFCVDEPTH_DEFAULT,
530	          int XFCVDEPTH_OUT_1 = _XFCVDEPTH_DEFAULT,
531	          int WORDWIDTH_SRC,
532	          int WORDWIDTH_DST,
533	          int COLS_TRIP>
534	void xFMulKernel(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_1>& src1,
535	                 xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_2>& src2,
536	                 xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_OUT_1>& dst,
537	                 int _policytype,
538	                 float _scale_val,
539	                 uint16_t image_height,
540	                 uint16_t image_width) {
541	    int STEP = XF_PIXELDEPTH(DEPTH) / PLANES;
542	    ap_uint<13> i, j, k;
543	    XF_SNAME(WORDWIDTH_SRC) val_src1, val_src2;
544	    XF_SNAME(WORDWIDTH_DST) val_dst;
545	
546	    XF_PTNAME(DEPTH) result, p, q;
547	    int64_t result_temp;
548	    uint16_t scale_value_8;
549	    uint32_t scale_value_16;
550	    if ((DEPTH == XF_8UP) || (DEPTH == XF_24UP)) {
551	        scale_value_8 = (_scale_val * ((1 << 15) - 1)); // floating point value taken in fixed point format (Q1.15)
552	    } else if ((DEPTH == XF_16SP) || (DEPTH == XF_48SP)) {
553	        scale_value_16 = (_scale_val * ((1 << 24) - 1)); // floating point value taken in fixed point format (Q1.24)
554	    }
555	    unsigned long long int idx = 0;
556	rowLoop:
557	    for (i = 0; i < image_height; i++) {
558	// clang-format off
559	        #pragma HLS LOOP_TRIPCOUNT min=ROWS max=ROWS
560	        #pragma HLS LOOP_FLATTEN off
561	    // clang-format on
562	
563	    colLoop:
564	        for (j = 0; j < image_width; j++) {
565	// clang-format off
566	            #pragma HLS LOOP_TRIPCOUNT min=COLS_TRIP max=COLS_TRIP
567	            #pragma HLS pipeline
568	            // clang-format on
569	
570	            val_src1 =
571	                (XF_SNAME(WORDWIDTH_SRC))(src1.read(i * image_width + j)); // reading the data from the first stream
572	            val_src2 =
573	                (XF_SNAME(WORDWIDTH_SRC))(src2.read(i * image_width + j)); // reading the data from the second stream
574	        procLoop:
575	            for (k = 0; k < (XF_WORDDEPTH(WORDWIDTH_SRC)); k += STEP) {
576	// clang-format off
577	                #pragma HLS unroll
578	                // clang-format on
579	                p = val_src1.range(k + (STEP - 1), k); // Get bits from certain range of positions.
580	                q = val_src2.range(k + (STEP - 1), k); // Get bits from certain range of positions.
581	
582	                // for the input type of 8U
583	                if ((DEPTH == XF_8UP) || (DEPTH == XF_24UP)) {
584	                    result_temp =
585	                        (scale_value_8 * p * q) >> 15; // performing pixel-wise multiplication with scale value
586	                    if (_policytype == XF_CONVERT_POLICY_SATURATE && result_temp > 255) // handling the overflow
587	                    {
588	                        result_temp = 255;
589	                    }
590	                    result = (uchar_t)result_temp;
591	                }
592	
593	                // for the input type of 16S
594	                else {
595	                    result_temp =
596	                        (scale_value_16 * p * q) >> 24; // performing pixel-wise multiplication with scale value
597	                    if (_policytype == XF_CONVERT_POLICY_SATURATE && result_temp > 32767) // handling the overflow
598	                    {
599	                        result_temp = 32767;
600	                    } else if (_policytype == XF_CONVERT_POLICY_SATURATE && result_temp < -32768) {
601	                        result_temp = -32768;
602	                    }
603	                    result = (int16_t)result_temp;
604	                }
605	                val_dst.range(k + (STEP - 1), k) = result; // Set bits in a range of positions.
606	            }
607	            dst.write(i * image_width + j, val_dst); // write data to the stream
608	        }
609	    }
610	}
