784	 * xFAdd: Adds the pixels of two input XF_8UP or XF_16SP images and generates the
785	 * 		  resultant image.
786	 * Inputs: _src1, _src2, _policytype
787	 * Output: _dst
788	 */
789	
790	template <int SRC_T,
791	          int ROWS,
792	          int COLS,
793	          int PLANES,
794	          int DEPTH,
795	          int NPC,
796	          int XFCVDEPTH_IN_1 = _XFCVDEPTH_DEFAULT,
797	          int XFCVDEPTH_IN_2 = _XFCVDEPTH_DEFAULT,
798	          int XFCVDEPTH_OUT_1 = _XFCVDEPTH_DEFAULT,
799	          int WORDWIDTH_SRC,
800	          int WORDWIDTH_DST,
801	          int COLS_TRIP,
802	          typename KERNEL,
803	          int USE_SRC2 = 0>
804	void xFarithm_proc(xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_1>& _src1,
805	                   xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_IN_2>& _src2,
806	                   xf::cv::Scalar<XF_CHANNELS(SRC_T, NPC), unsigned char> scl,
807	                   xf::cv::Mat<SRC_T, ROWS, COLS, NPC, XFCVDEPTH_OUT_1>& _dst,
808	                   int _policytype,
809	                   uint16_t image_height,
810	                   uint16_t image_width) {
811	    KERNEL opr;
812	    int STEP;
813	    STEP = XF_PIXELDEPTH(DEPTH) / PLANES;
814	    ap_uint<13> i, j, k;
815	    XF_SNAME(WORDWIDTH_SRC) val_src1 = 0, val_src2 = 0;
816	    XF_SNAME(WORDWIDTH_DST) val_dst = 0;
817	    XF_PTNAME(DEPTH) result, p = 0, q = 0;
818	
819	rowLoop:
820	    for (i = 0; i < image_height; i++) {
821	// clang-format off
822	        #pragma HLS LOOP_TRIPCOUNT min=ROWS max=ROWS
823	        #pragma HLS LOOP_FLATTEN off
824	    // clang-format on
825	
826	    colLoop:
827	        for (j = 0; j < image_width; j++) {
828	// clang-format off
829	            #pragma HLS LOOP_TRIPCOUNT min=COLS_TRIP max=COLS_TRIP
830	            #pragma HLS pipeline
831	            // clang-format on
832	            val_src1 =
833	                (XF_SNAME(WORDWIDTH_SRC))(_src1.read(i * image_width + j)); // reading the data from the first stream
834	            if (USE_SRC2) {
835	                val_src2 = (XF_SNAME(WORDWIDTH_SRC))(_src2.read(i * image_width + j));
836	            }
837	        procLoop:
838	            for (k = 0; k < (XF_WORDDEPTH(WORDWIDTH_SRC)); k += STEP) {
839	// clang-format off
840	                #pragma HLS unroll
841	                // clang-format on
842	                p = val_src1.range(k + (STEP - 1), k); // Get bits from certain range of positions.
843	                if (USE_SRC2) {
844	                    q = val_src2.range(k + (STEP - 1), k);
845	                } else {
846	                    q = scl.val[0];
847	                }
848	
849	                opr.template apply<DEPTH>(p, q, result, _policytype);
850	
851	                val_dst.range(k + (STEP - 1), k) = result; // Set bits in a range of positions.
852	            }
853	            _dst.write(i * image_width + j, val_dst); // writing data to the output stream
854	        }
855	    }
856	}
