            ]
        },
        "linker" : {
            "libraries" : [
                "opencv_videoio",
                "opencv_imgcodecs",
                "opencv_core",
                "opencv_imgproc",
                "opencv_features2d",
                "opencv_flann",
				"opencv_video",
				"opencv_calib3d",
